// kitPerfWarmup is how many calls run before the window opens: enough
// that the runtime's lazily built caches — a type switch's or a type
// assertion's, built on about one miss in 1024 — are paid outside it (left
// unbuilt with a probability near 2e-13).
const kitPerfWarmup = 30000

// kitPerfRuns is how many calls the window counts: as many as the warm-up,
// so that a slice growing by doubling, which the warm-up grew too, crosses
// one of its growth steps inside the window all the same.
const kitPerfRuns = 30000

// kitPerfMallocs is the TOTAL number of heap allocations kitPerfRuns calls
// of f perform, never their integer average (testing.AllocsPerRun reads a
// call that allocates on some runs only as 0). GOMAXPROCS is pinned so that
// no other P allocates into the count, the collector is held off for the
// warm-up and the window (a collection drains a sync.Pool, whose refill is
// no call's cost), and whatever the pin left runnable runs to its park
// first. The tests that call it are not parallel: these settings are the
// process's.
func kitPerfMallocs(f func()) uint64 {
	defer runtime.GOMAXPROCS(runtime.GOMAXPROCS(1))
	defer debug.SetGCPercent(debug.SetGCPercent(-1))
	runtime.Gosched()
	for range kitPerfWarmup {
		f()
	}
	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	for range kitPerfRuns {
		f()
	}
	runtime.ReadMemStats(&after)
	return after.Mallocs - before.Mallocs
}

